    invokeMethod(Preconditions.class, "checkArgument", new Class[] { boolean.class, String.class, int.class }, null, true, "Error Message %s", 1);
    try {
        invokeMethod(Preconditions.class, "checkArgument", new Class[] { boolean.class, String.class, int.class }, null, false, "Error Message %s", 1);
